int n = 100_000;
long periodNs = 50_000;          // 20,000 건/초로 고정

long t0 = System.nanoTime();
for (int i = 0; i < n; i++) {
    long due = t0 + i * periodNs;                 // 나가야 할 시각
    long now;
    while ((now = System.nanoTime()) < due) Thread.onSpinWait();
    request(i);
    long end = System.nanoTime();
    service[i]  = end - now;                      // 일한 시간
    response[i] = end - due;                      // 기다린 시간까지
}
